CustomField.formula:
/* Objetivo: Retornar a situação de crédito do cliente considerando aprovação, rejeição financeira, forma de pagamento, condição de pagamento e bloqueios de crédito.
As condições de pagamento 000 e 001 são desconsideradas nas regras específicas de Suframa e Depósito. */
IF( /* 1. Se o crédito já estiver aprovado, retorna "Crédito aprovado". */ AprovaCredito__c,
"Crédito aprovado",
/* 2. Caso não esteja aprovado, verifica se a forma de pagamento exige análise ou bloqueio financeiro. */ IF( OR( TEXT(FormaDePagamento__c) = "BN - BNDS", TEXT(FormaDePagamento__c) = "SI - SIFRA", TEXT(FormaDePagamento__c) = "BV - BV", TEXT(FormaDePagamento__c) = "MP - MPAY", TEXT(FormaDePagamento__c) = "IC- ICMS", TEXT(FormaDePagamento__c) = "RS - Risco sacado",
/* Suframa só será considerada bloqueada quando a condição de pagamento NÃO for 000 nem 001. */ AND( TEXT(FormaDePagamento__c) = "SF-Suframa", NOT( OR( CondicaoPagamento__r.codigo__c = "002", CondicaoPagamento__r.codigo__c = "001" ) ) ),
TEXT(FormaDePagamento__c) = "DP - Duplicata",
/* Depósito só será considerado bloqueado quando a condição de pagamento NÃO for 000 nem 001. */ AND( TEXT(FormaDePagamento__c) = "DE- Depósito", NOT( OR( CondicaoPagamento__r.codigo__c = "002", CondicaoPagamento__r.codigo__c = "001" ) ) ),
TEXT(FormaDePagamento__c) = "ID - ICMS/DUPLICATA" ),
/* 3. Para formas de pagamento com regra de bloqueio: se foi rejeitada pelo financeiro, retorna rejeição. Caso contrário, retorna bloqueio de crédito. */ IF( RejeitadaCredito__c, "Rejeitada Financeiro", "Cliente com bloqueio de crédito" ),
/* 4. Para as demais formas de pagamento, verifica se o cliente pode seguir sem bloqueio. */ IF( OR( AND( NOT(BloqueioFinanceiro__c), CreditodisponivelMaisPolimeros__c > 0 ),
NOT(IsBloqueioCreditoCondPag__c),
NOT(IsBloqueioCreditoTES__c) ),
"Cliente sem bloqueio",
/* 5. Caso não tenha liberação, valida se foi rejeitado. */ IF( RejeitadaCredito__c, "Rejeitada Financeiro", "Cliente com bloqueio de crédito" ) ) ) )
/* Regra antiga ou futura: Account.ValorOportunidadesAbertas__c <= LimiteCreditoConta__c */
